use verus::prelude::*;

verus! {

    /// Broadcast two non‐empty `Vec<i8>`s under the usual numpy‐style
    /// broadcasting rules: either the vectors have the same length,
    /// or one of them has length 1.  Returns two vectors of length
    /// `max(a.len(), b.len())` obtained by repeating the singleton
    /// if needed.
    fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>)
        requires
            a.len() >= 1,
            b.len() >= 1,
            // shape‐compatibility: same length, or one of them is 1
            a.len() == b.len() || a.len() == 1 || b.len() == 1,
        ensures
            // Let L = max(a.len(), b.len())
            |(res_x, res_y): (Vec<i8>, Vec<i8>)| {
                let L = if a.len() >= b.len() { a.len() } else { b.len() };
                // both results have length L
                res_x.len() == L &&
                res_y.len() == L &&
                // each index i in [0, L) respects broadcasting
                forall |i: usize| i < L ==>
                    (
                        // x matches a
                        if a.len() == L {
                            res_x[i] == a[i]
                        } else {
                            // then a.len() == 1
                            res_x[i] == a[0]
                        }
                    ) &&
                forall |i: usize| i < L ==>
                    (
                        // y matches b
                        if b.len() == L {
                            res_y[i] == b[i]
                        } else {
                            // then b.len() == 1
                            res_y[i] == b[0]
                        }
                    )
            }
    {
        // compute L = max(a.len(), b.len())
        let L: usize = if a.len() >= b.len() { a.len() } else { b.len() };

        // prepare outputs
        let mut x: Vec<i8> = Vec::new();
        let mut y: Vec<i8> = Vec::new();

        // fill them index by index
        let mut i: usize = 0;
        while i < L
            invariant i <= L
            invariant x.len() == i
            invariant y.len() == i
            decreases L - i
        {
            // pick from a, either a[0] if singleton, or a[i] otherwise
            let av: i8;
            if a.len() == 1 {
                av = a[0];
            } else {
                // if not a singleton, by shape‐compatibility a.len() == L,
                // so i < L implies i < a.len()
                assert(i < a.len());
                av = a[i];
            }

            // same for b
            let bv: i8;
            if b.len() == 1 {
                bv = b[0];
            } else {
                assert(i < b.len());
                bv = b[i];
            }

            x.push(av);
            y.push(bv);
            i = i + 1;
        }

        (x, y)
    }

}